#!/usr/bin/env python3
"""The five different counts of the LeetCode-style corpus, never mixed up:
unique_problems | unique_code_implementations | training_examples (views, NOT independent) | reasoning_annotations | verified_implementations (under the runner definition).
  python3 tools/corpus_counts.py            -> prints COUNTS.md text and writes COUNTS.md + counts.json"""
import glob, gzip, hashlib, json, os, sys, collections
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import validate_notes as V

def jl(path):
    op = gzip.open if path.endswith(".gz") else open
    return [json.loads(l) for l in op(path, "rt", encoding="utf-8") if l.strip()]
sha = lambda s: hashlib.sha256(s.encode("utf-8", "replace")).hexdigest()
chat = [r for f in sorted(glob.glob("data/solutions/*.jsonl")) for r in jl(f)]
U = jl("corpus/unified/solutions.jsonl.gz"); mined = [u for u in U if u.get("source") != "chatgpt"]
sft_plain = len(jl("corpus/unified/sft_plain.jsonl.gz")); sft_think = len(jl("corpus/unified/sft_think.jsonl.gz")); qa_unified = len(jl("corpus/unified/qa_sft.jsonl.gz"))
qa_chat = sum(len(jl(f)) for f in glob.glob("data/qa/*.jsonl"))
locked = {int(x) for x in open("locked/locked_leetcode_numbers.txt").read().split() if x.strip().isdigit()}
pc, pm = {int(r["number"]) for r in chat}, {int(u["number"]) for u in mined}
both_langs = sum(1 for n in pc | pm if {u["language"] for u in mined if int(u["number"]) == n} & {"python3"} and {u["language"] for u in mined if int(u["number"]) == n} & {"java"}) if False else None
lang_by_problem = collections.defaultdict(set)
for u in mined: lang_by_problem[int(u["number"])].add(u["language"])
for r in chat: lang_by_problem[int(r["number"])].add("python3" if r["language"].startswith("python") else "java")
code_hashes = {sha(r["code"]) for r in chat} | {sha(u["code"]) for u in mined}
notes_chat = sum(1 for r in chat if r.get("notes")); chat_pass = sum(1 for r in chat if not V.check(r))
ann = [json.loads(l) for f in glob.glob("annotated/*.jsonl") for l in open(f, encoding="utf-8") if l.strip()]
ann2 = [json.loads(l) for f in glob.glob("annotated2/*.jsonl") for l in open(f, encoding="utf-8") if l.strip()]
doocs_think = sum(1 for u in mined if u.get("source") == "doocs" and u.get("think"))
tier = collections.Counter(u.get("tier") for u in mined)
c = {
 "unique_problems": {"chatgpt_written": len(pc), "mined_with_solutions": len(pm), "union": len(pc | pm), "union_with_python_and_java": sum(1 for n, s in lang_by_problem.items() if {"python3", "java"} <= s), "locked_excluded_numbers": len(locked), "overlap_with_locked": len((pc | pm) & locked)},
 "unique_code_implementations": {"chatgpt_records": len(chat), "mined_records": len(mined), "unique_by_code_hash": len(code_hashes)},
 "training_examples_views_not_independent": {"sft_plain_in_unified_(stale_for_chatgpt)": sft_plain, "sft_think_in_unified": sft_think, "qa_unified": qa_unified, "qa_chatgpt_now": qa_chat},
 "reasoning_annotations": {"chatgpt_solution_notes_total": notes_chat, "chatgpt_notes_passing_validator": chat_pass, "annotated_mined_python_v1_lines": len(ann), "annotated_mined_python_v1_unique_ids": len({a["id"] for a in ann}), "annotated2_v2": len(ann2), "doocs_thinking_blocks": doocs_think},
 "verified_implementations": {"verified_under_runner_definition": 0, "public_examples_passed_by_runner": 12, "mined_tier_A_complexity_label_and_examples_passed": tier["A"], "mined_tier_B_examples_passed": tier["B"], "mined_tier_C_no_runnable_example": tier["C"], "mined_tier_D_example_failed": tier["D"],
                              "chatgpt_status_verified_by_its_own_claim": sum(1 for r in chat if r.get("status") == "verified"), "chatgpt_status_pending": sum(1 for r in chat if r.get("status") == "pending")},
}
json.dump(c, open("counts.json", "w"), indent=1)
md = ["# Corpus counts (generated by tools/corpus_counts.py)", "", "Five different things. Do not add them together.", ""]
for k, v in c.items():
    md += [f"## {k}", ""] + [f"- {a}: {b:,}" for a, b in v.items()] + [""]
md += ["Notes: `unified/` was built before the notes fixes, so its ChatGPT part is stale (rebuild with tools/unify_corpus.py). SFT 'views' are alternative renderings of the same solutions (plain / with think), not separate examples.",
       "`verified_under_runner_definition` = 0 because the runner (tools/verify_records.py in the code repo) only gives `verified` to stdin/stdout programs with >= 8 passing tests; LeetCode-style records top out at `public_tests_passed`."]
open("COUNTS.md", "w").write("\n".join(md) + "\n"); print("\n".join(md))
